<?php
require_once __DIR__.'/../notices.php';$dashboardNotices=oecrm_employee_notices($conn,(int)$employeeId,8);$dashboardNoticeRows=[];$popupNotice=null;while($dn=mysqli_fetch_assoc($dashboardNotices)){$dashboardNoticeRows[]=$dn;if(!$popupNotice&&$dn['show_popup']&&!$dn['read_at'])$popupNotice=$dn;}foreach($dashboardNoticeRows as $dn){if(!$dn['first_seen_at']){$s=mysqli_prepare($conn,'INSERT INTO notice_receipts(notice_id,employee_id,first_seen_at) VALUES(?,?,NOW()) ON DUPLICATE KEY UPDATE first_seen_at=COALESCE(first_seen_at,NOW())');mysqli_stmt_bind_param($s,'ii',$dn['id'],$employeeId);mysqli_stmt_execute($s);mysqli_stmt_close($s);oecrm_notice_event($conn,(int)$dn['id'],$employeeId,'employee',$employeeId,'view','Notice displayed on dashboard');}}
?>
<?php if($dashboardNoticeRows):?><section class="dashboard-notices"><div class="dashboard-notice-head"><div><h4><i class="fa fa-bullhorn"></i> Notices</h4><span><?php echo count($dashboardNoticeRows);?> active announcement<?php echo count($dashboardNoticeRows)===1?'':'s';?></span></div><a href="notices.php">View all</a></div><div class="dashboard-notice-items"><?php foreach(array_slice($dashboardNoticeRows,0,3) as $dn):?><a href="notices.php" class="dashboard-notice-item priority-<?php echo htmlspecialchars($dn['priority']);?>"><span class="notice-dot"></span><div><strong><?php echo htmlspecialchars($dn['title'],ENT_QUOTES,'UTF-8');?></strong><small><?php echo htmlspecialchars(ucfirst($dn['notice_type']));?> notice | <?php echo date('d M Y',strtotime($dn['publish_at']));?></small></div><?php if(!$dn['read_at']):?><span class="new-label">New</span><?php endif;?></a><?php endforeach;?></div></section><?php endif;?>
<?php if($popupNotice):?><div class="modal fade notice-popup" id="noticePopup" tabindex="-1" role="dialog"><div class="modal-dialog"><div class="modal-content"><div class="notice-popup-accent priority-<?php echo htmlspecialchars($popupNotice['priority']);?>"></div><div class="modal-header"><button type="button" class="close" data-dismiss="modal">&times;</button><span class="notice-priority <?php echo $popupNotice['priority'];?>"><?php echo ucfirst($popupNotice['priority']);?></span><h4 class="modal-title"><?php echo htmlspecialchars($popupNotice['title'],ENT_QUOTES,'UTF-8');?></h4></div><div class="modal-body"><div class="employee-notice-body"><?php echo $popupNotice['body_html'];?></div></div><div class="modal-footer"><a class="btn btn-default" href="notices.php">Open Notice Center</a><form method="post" action="noticeAction.php" style="display:inline"><?php echo oecrm_csrf_field();?><input type="hidden" name="notice_id" value="<?php echo (int)$popupNotice['id'];?>"><button name="action" value="<?php echo $popupNotice['acknowledgement_required']?'acknowledge':'read';?>" class="btn btn-primary"><?php echo $popupNotice['acknowledgement_required']?'Acknowledge':'Mark as Read';?></button></form></div></div></div></div><script>$(function(){ $('#noticePopup').modal('show'); });</script><?php endif;?>
